67:       const [statsData, docsData, companyData] = await Promise.all([
68:         getCompanyStats(),
69:         getDocuments(1, 4).catch((e) => {
70:           console.warn("Could not fetch recent documents:", e);
71:           return { items: [] };
72:         }),
73:         getCompanyInfo().catch((e) => {
