93:         let attempts = 0;
94:         const interval = setInterval(async () => {
95:           try {
96:             const statusData = await pollDocumentStatus(doc.id);
97:             if (statusData.status === "completed" || statusData.status === "failed") {
98:               clearInterval(interval);
99:               delete activePollsRef.current[doc.id];
100:               // Silent reload of data when any processing file finishes
101:               reloadStatsAndDocs();
102:             } else {
103:               // Update local state dynamically to show live stage updates
104:               setRecentDocs((prevDocs) =>
105:                 prevDocs.map((item) =>
106:                   item.id === doc.id
107:                     ? { ...item, status: statusData.status, error_message: statusData.error_message }
108:                     : item
109:                 )
110:               );
111:             }
112:           } catch (err) {
113:             console.error(`Status polling failed on dashboard for ${doc.id}:`, err);
114:             attempts++;
115:             if (attempts > 10) {
116:               clearInterval(interval);
117:               delete activePollsRef.current[doc.id];
118:             }
119:           }
120:         }, 3000);
121: 
122:         activePollsRef.current[doc.id] = () => clearInterval(interval);
123:       });
124: 
125:     } catch (err: unknown) {
126:       console.error("Dashboard overview API error:", err);
127:       const errMsg = err instanceof Error ? err.message : String(err);
128:       setError(errMsg || "Failed to establish secure connection to workspace backend.");
