function CodeBlock({ code, lang }: { code: string; lang: string }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (e) {
      console.warn("Failed to copy code block:", e);
    }
  };

  return (
    <div className="my-3.5 border-2 border-black dark:border-white bg-[#1E1E24] text-slate-105 rounded-xl overflow-hidden shadow-[3px_3px_0px_#000000] dark:shadow-[3px_3px_0px_#FFFFFF] w-full max-w-full">
      <div className="px-4 py-2 bg-[#2D2D36] border-b-2 border-black dark:border-b-white flex items-center justify-between font-mono text-[9px] uppercase tracking-wider font-extrabold text-slate-350 select-none">
        <span>{lang || "code"}</span>
        <button
          onClick={handleCopy}
          className="flex items-center space-x-1 hover:text-white transition-all cursor-pointer font-black text-slate-300"
        >
          {copied ? (
            <>
              <Check className="w-3.5 h-3.5 text-emerald-400 shrink-0" />
              <span className="text-emerald-450">Copied!</span>
            </>
          ) : (
            <>
              <Copy className="w-3.5 h-3.5 shrink-0" />
              <span>Copy Code</span>
            </>
          )}
        </button>
      </div>
      <pre className="p-4 overflow-x-auto text-[10px] sm:text-[11px] font-mono leading-relaxed select-all max-w-full bg-[#18181C]">
        <code className="text-[#E0E0E0]">{code}</code>
      </pre>
    </div>
  );
}

function parseInlineMarkdown(text: string): React.ReactNode {
  if (!text) return "";
  const tokenRegex = /(\*\*.*?\*\*|`.*?`|\[.*?\]\(.*?\))/g;
  const parts = text.split(tokenRegex);

  return parts.map((part, index) => {
    if (part.startsWith("**") && part.endsWith("**")) {
      return (
        <strong key={index} className="font-black text-black dark:text-white">
          {part.substring(2, part.length - 2)}
        </strong>
      );
    }
    if (part.startsWith("`") && part.endsWith("`")) {
      return (
        <code key={index} className="px-1.5 py-0.5 rounded bg-slate-150 dark:bg-slate-800 text-[10px] sm:text-xs font-mono border border-slate-300 dark:border-slate-700 text-rose-600 dark:text-rose-400 font-bold select-all">
          {part.substring(1, part.length - 1)}
        </code>
      );
    }

    const linkMatch = part.match(/^\[(.*?)\]\((.*?)\)$/);
    if (linkMatch) {
      const label = linkMatch[1];
      const url = linkMatch[2];
      return (
        <a
          key={index}
          href={url}
          target="_blank"
          rel="noopener noreferrer"
          className="text-purple-650 dark:text-purple-400 font-extrabold underline hover:text-purple-750 dark:hover:text-purple-300 transition-colors"
        >
          {label}
        </a>
      );
    }

    return part;
  });
}

function parseMarkdownSubtext(subtext: string): React.ReactNode[] {
  const lines = subtext.split("\n");
  const blocks: React.ReactNode[] = [];

  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    const trimmed = line.trim();

    if (trimmed === "") {
      i++;
      continue;
    }

    // 1. Blockquote
    if (trimmed.startsWith(">")) {
      const quoteLines: string[] = [];
      while (i < lines.length && lines[i].trim().startsWith(">")) {
        const content = lines[i].trim().substring(1).trim();
        quoteLines.push(content);
        i++;
      }
      blocks.push(
        <blockquote key={`quote-${i}`} className="my-3 pl-4 border-l-4 border-purple-500 italic text-slate-650 dark:text-slate-400 font-semibold leading-relaxed">
          {quoteLines.map((ql, idx) => (
            <p key={idx}>{parseInlineMarkdown(ql)}</p>
          ))}
        </blockquote>
      );
      continue;
    }

    // 2. Table
    if (trimmed.startsWith("|")) {
      const tableLines: string[] = [];
      while (i < lines.length && lines[i].trim().startsWith("|")) {
        tableLines.push(lines[i].trim());
        i++;
      }

      if (tableLines.length >= 2) {
        const headers = tableLines[0]
          .split("|")
          .map(s => s.trim())
          .filter((_, idx, arr) => idx > 0 && idx < arr.length - 1);

        const rowsData = tableLines.slice(2).map(rowLine => {
          return rowLine
            .split("|")
            .map(s => s.trim())
            .filter((_, idx, arr) => idx > 0 && idx < arr.length - 1);
        });

        blocks.push(
          <div key={`table-${i}`} className="my-3.5 overflow-x-auto border-2 border-black dark:border-white rounded-xl shadow-[3px_3px_0px_#000000] dark:shadow-[3px_3px_0px_#FFFFFF] max-w-full">
            <table className="min-w-full divide-y-2 divide-black dark:divide-white text-xs text-left">
              <thead className="bg-slate-100 dark:bg-[#25252A] font-black uppercase text-[9px] sm:text-[10px] tracking-wider text-black dark:text-white select-none">
                <tr>
                  {headers.map((h, hidx) => (
                    <th key={hidx} className="px-4 py-2.5 border-r-2 border-black last:border-r-0 dark:border-white">
                      {parseInlineMarkdown(h)}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200 dark:divide-slate-700 bg-white dark:bg-[#1E1E22] text-slate-705 dark:text-slate-350">
                {rowsData.map((row, rowIdx) => (
                  <tr key={rowIdx} className="hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors">
                    {row.map((cell, cellIdx) => (
                      <td key={cellIdx} className="px-4 py-2 border-r border-slate-200 last:border-r-0 dark:border-slate-700 font-semibold leading-relaxed">
                        {parseInlineMarkdown(cell)}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        );
        continue;
      }
    }

    // 3. Unordered List
    if (trimmed.startsWith("- ") || trimmed.startsWith("* ") || trimmed.startsWith("• ")) {
      const listItems: string[] = [];
      while (i < lines.length) {
        const nextTrim = lines[i].trim();
        if (nextTrim.startsWith("- ") || nextTrim.startsWith("* ") || nextTrim.startsWith("• ")) {
          listItems.push(nextTrim.substring(2).trim());
          i++;
        } else {
          break;
        }
      }
      blocks.push(
        <ul key={`ul-${i}`} className="my-2.5 pl-6 list-disc space-y-1 text-slate-800 dark:text-slate-205 text-xs sm:text-sm font-semibold leading-relaxed">
          {listItems.map((item, idx) => (
            <li key={idx} className="pl-0.5">{parseInlineMarkdown(item)}</li>
          ))}
        </ul>
      );
      continue;
    }

    // 4. Ordered List
    const matchOrdered = trimmed.match(/^(\d+)\.\s+(.*)/);
    if (matchOrdered) {
      const listItems: string[] = [];
      while (i < lines.length) {
        const nextTrim = lines[i].trim();
        const nextMatch = nextTrim.match(/^(\d+)\.\s+(.*)/);
        if (nextMatch) {
          listItems.push(nextMatch[2].trim());
          i++;
        } else {
          break;
        }
      }
      blocks.push(
        <ol key={`ol-${i}`} className="my-2.5 pl-6 list-decimal space-y-1 text-slate-800 dark:text-slate-205 text-xs sm:text-sm font-semibold leading-relaxed">
          {listItems.map((item, idx) => (
            <li key={idx} className="pl-0.5">{parseInlineMarkdown(item)}</li>
          ))}
        </ol>
      );
      continue;
    }

    // 5. Paragraph
    blocks.push(
      <p key={`p-${i}`} className="mb-2 text-slate-800 dark:text-slate-200 last:mb-0 leading-relaxed font-semibold">
        {parseInlineMarkdown(trimmed)}
      </p>
    );
    i++;
  }

  return blocks;
}

const formatMessageText = (text: string) => {
  if (!text) return null;
  const parts = text.split("```");
  const blocks: React.ReactNode[] = [];

  for (let i = 0; i < parts.length; i++) {
    if (i % 2 === 1) {
      const part = parts[i];
      const lines = part.split("\n");
      const lang = lines[0].trim();
      const code = lines.slice(1).join("\n").trim();
      blocks.push(
        <CodeBlock key={`code-${i}`} code={code} lang={lang} />
      );
    } else {
      const subtext = parts[i];
      const subBlocks = parseMarkdownSubtext(subtext);
      blocks.push(...subBlocks);
    }
  }

  return <div className="space-y-1 w-full max-w-full break-words">{blocks}</div>;
};

args.TargetContent:
const formatMessageText = (text: string) => {
  if (!text) return null;
  const lines = text.split("\n");

  // Keep track of whether we are inside a bulleted list to group <li> items
  let inList = false;
  const elements: React.ReactNode[] = [];
  let currentListItems: React.ReactNode[] = [];

  const parseLine = (lineContent: string, lineIdx: number) => {
    // Parse bold text **bold**
    const parts = [];
    const boldRegex = /\*\*([^*]+)\*\*/g;
    let match;
    let lastIndex = 0;

    while ((match = boldRegex.exec(lineContent)) !== null) {
      const matchIndex = match.index;
      if (matchIndex > lastIndex) {
        parts.push(lineContent.substring(lastIndex, matchIndex));
      }
      parts.push(
        <strong key={`bold-${lineIdx}-${matchIndex}`} className="font-extrabold text-black dark:text-white">
          {match[1]}
        </strong>
      );
      lastIndex = boldRegex.lastIndex;
    }

    if (lastIndex < lineContent.length) {
      parts.push(lineContent.substring(lastIndex));
    }

    return parts.length > 0 ? parts : lineContent;
  };

  lines.forEach((line, lineIdx) => {
    const isBullet = line.trim().startsWith("- ") || line.trim().startsWith("* ") || line.trim().startsWith("• ");

    if (isBullet) {
      if (!inList) {
        inList = true;
        currentListItems = [];
      }
      const lineContent = line.trim().replace(/^[-*•]\s+/, "");
      currentListItems.push(
        <li key={`li-${lineIdx}`} className="ml-4 list-disc mb-1 pl-1 text-slate-800 dark:text-slate-205">
          {parseLine(lineContent, lineIdx)}
        </li>
      );
    } else {
      if (inList) {
        inList = false;
        elements.push(
          <ul key={`ul-${lineIdx}`} className="my-2 space-y-1">
            {currentListItems}
          </ul>
        );
        currentListItems = [];
      }

      const trimmed = line.trim();
      elements.push(
        trimmed === "" ? (
          <div key={`space-${lineIdx}`} className="h-3" />
        ) : (
          <p key={`p-${lineIdx}`} className="mb-2 text-slate-800 dark:text-slate-200">
            {parseLine(line, lineIdx)}
          </p>
        )
      );
    }
  });

  if (inList) {
    elements.push(
      <ul key="ul-end" className="my-2 space-y-1">
        {currentListItems}
      </ul>
    );
  }

  return <div className="space-y-1">{elements}</div>;
};

