+            .map(s => s.trim())
+            .filter((_, idx, arr) => idx > 0 && idx < arr.length - 1);
+        });
+
+        blocks.push(
+          <div key={`table-${i}`} className="my-3.5 overflow-x-auto border-2 border-black dark:border-white rounded-xl shadow-[3px_3px_0px_#000000] dark:shadow-[3px_3px_0px_#FFFFFF] max-w-full">
+            <table className="min-w-full divide-y-2 divide-black dark:divide-white text-xs text-left">
+              <thead className="bg-slate-100 dark:bg-[#25252A] font-black uppercase text-[9px] sm:text-[10px] tracking-wider text-black dark:text-white select-none">
+                <tr>
+                  {headers.map((h, hidx) => (
+                    <th key={hidx} className="px-4 py-2.5 border-r-2 border-black last:border-r-0 dark:border-white">
+                      {parseInlineMarkdown(h)}
+                    </th>
+                  ))}
+                </tr>
+              </thead>
+              <tbody className="divide-y divide-slate-200 dark:divide-slate-700 bg-white dark:bg-[#1E1E22] text-slate-705 dark:text-slate-350">
+                {rowsData.map((row, rowIdx) => (
+                  <tr key={rowIdx} className="hover:bg-slate-50 dark:hover:bg-slate-800 transition-colors">
+                    {row.map((cell, cellIdx) => (
+                      <td key={cellIdx} className="px-4 py-2 border-r border-slate-200 last:border-r-0 dark:border-slate-700 font-semibold leading-relaxed">
+                        {parseInlineMarkdown(cell)}
+                      </td>
