+    // 3. Unordered List
+    if (trimmed.startsWith("- ") || trimmed.startsWith("* ") || trimmed.startsWith("• ")) {
+      const listItems: string[] = [];
+      while (i < lines.length) {
+        const nextTrim = lines[i].trim();
+        if (nextTrim.startsWith("- ") || nextTrim.startsWith("* ") || nextTrim.startsWith("• ")) {
+          listItems.push(nextTrim.substring(2).trim());
+          i++;
+        } else {
+          break;
+        }
+      }
+      blocks.push(
+        <ul key={`ul-${i}`} className="my-2.5 pl-6 list-disc space-y-1 text-slate-800 dark:text-slate-205 text-xs sm:text-sm font-semibold leading-relaxed">
+          {listItems.map((item, idx) => (
+            <li key={idx} className="pl-0.5">{parseInlineMarkdown(item)}</li>
+          ))}
+        </ul>
+      );
+      continue;
+    }
+
+    // 4. Ordered List
+    const matchOrdered = trimmed.match(/^(\d+)\.\s+(.*)/);
+    if (matchOrdered) {
+      const listItems: string[] = [];
+      while (i < lines.length) {
