+          {listItems.map((item, idx) => (
+            <li key={idx} className="pl-0.5">{parseInlineMarkdown(item)}</li>
+          ))}
+        </ol>
+      );
+      continue;
+    }
+
+    // 5. Paragraph
+    blocks.push(
+      <p key={`p-${i}`} className="mb-2 text-slate-800 dark:text-slate-200 last:mb-0 leading-relaxed font-semibold">
+        {parseInlineMarkdown(trimmed)}
+      </p>
+    );
+    i++;
+  }
+
+  return blocks;
+}
+
+const formatMessageText = (text: string) => {
+  if (!text) return null;
+  const parts = text.split("```");
+  const blocks: React.ReactNode[] = [];
+
+  for (let i = 0; i < parts.length; i++) {
+    if (i % 2 === 1) {
+      const part = parts[i];
+      const lines = part.split("\n");
+      const lang = lines[0].trim();
+      const code = lines.slice(1).join("\n").trim();
+      blocks.push(
+        <CodeBlock key={`code-${i}`} code={code} lang={lang} />
+      );
+    } else {
+      const subtext = parts[i];
+      const subBlocks = parseMarkdownSubtext(subtext);
+      blocks.push(...subBlocks);
+    }
+  }
+
+  return <div className="space-y-1 w-full max-w-full break-words">{blocks}</div>;
+};;
